# User provides some values but leaves essential ones empty env_overrides = { "GITHUB_PERSONAL_ACCESS_TOKEN": "ghp_token_123", "GITHUB_TOOLSETS": "", # Empty - should get default "GITHUB_HOST": "", # Empty - no default needed (optional) "GITHUB_READ_ONLY": "1", # User provided value "GITHUB_DYNAMIC_TOOLSETS": "", # Empty - should get default }
with patch.object(adapter, "registry_client") as mock_registry: mock_registry.find_server_by_reference.return_value = github_mcp_server_data
result = adapter.configure_mcp_server( "io.github.github/github-mcp-server", env_overrides=env_overrides )
assert result is True
